def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    total = 0.0
    spheres = 0.0
    for t in sites:
        o = t.get('occupancy')
        o = max(0.0, o if o is not None else 1.0)
        p = props.get(t.get('element')) or {}
        r = p.get('covalent_radius_A')
        if r is None or not isfinite(r) or r <= 0:
            r = 1.3
        total += o
        spheres += o * r * r * r
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or not isfinite(volume) or volume <= 0:
        v = s.get('volume_per_atom_A3')
        volume = v * total if v is not None and isfinite(v) and v > 0 else 0.0
    return 4.0 * pi * spheres / (3.0 * volume) if volume > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = []
    occ = []
    for t in sites:
        r = (props.get(t.get('element')) or {}).get('covalent_radius_A')
        radii.append(r if r is not None and isfinite(r) and r > 0 else 1.3)
        o = t.get('occupancy')
        occ.append(max(0.0, o if o is not None else 1.0))
    n = len(sites)
    best = inf
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[i] > 0 and occ[j] > 0 and d is not None and isfinite(d) and d > 0:
            best = min(best, d / (radii[i] + radii[j]))
    return best if isfinite(best) else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    occ = []
    for t in sites:
        o = t.get('occupancy')
        occ.append(max(0.0, o if o is not None else 1.0))
    nearest = [inf for t in sites]
    next_shell = [inf for t in sites]
    bonds = s.get('neighbors') or []
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[j] > 0 and d is not None and isfinite(d) and d > 0:
            nearest[i] = min(nearest[i], d)
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[j] > 0 and d is not None and isfinite(d) and d > 1.10 * nearest[i]:
            next_shell[i] = min(next_shell[i], d)
    total = 0.0
    result = 0.0
    for i in range(n):
        if isfinite(nearest[i]) and isfinite(next_shell[i]) and nearest[i] > 0:
            result += occ[i] * (next_shell[i] / nearest[i] - 1.0)
            total += occ[i]
    return result / total if total > 0 else 0.0

