    total = 0.0
    known = 0.0
    electrons = 0.0
    for t in sites:
        o = t.get('occupancy')
        o = max(0.0, o if o is not None else 1.0)
        total += o
        v = (props.get(t.get('element')) or {}).get('valence_electrons')
        if v is not None and isfinite(v) and v >= 0:
            electrons += o * v
            known += o
    if total <= 0 or known <= 0:
        return 0.0
